using Microsoft.AspNetCore.Http;

using NumberSearch.DataAccess.FusionPBX;

using Serilog;

using System;
using System.Threading.Tasks;

namespace Messaging
{
    /// <summary>
    /// Authenticates requests to the Messaging API using API keys generated by existing user accounts in FusionPBX,
    /// and restricts those requests to the phone numbers the user owns (the destinations registered to their domain).
    /// This runs alongside the existing ops.acceleratenetworks.com Identity bearer token authorization: an operator
    /// token continues to work unrestricted, while a FusionPBX key is scoped to the caller's own numbers.
    /// </summary>
    public static class FusionPBXAuth
    {
        /// <summary>
        /// Pulls the raw bearer token out of the Authorization header, if present.
        /// </summary>
        public static string? GetBearerToken(HttpContext context)
        {
            string? header = context.Request.Headers.Authorization;

            if (string.IsNullOrWhiteSpace(header))
            {
                return null;
            }

            const string prefix = "Bearer ";
            return header.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)
                ? header[prefix.Length..].Trim()
                : header.Trim();
        }

        /// <summary>
        /// Resolves the bearer token to an enabled FusionPBX user, or returns a default User (user_uuid == Guid.Empty)
        /// when the token is not a valid FusionPBX API key. A default result means "not a FusionPBX request" and the
        /// caller should fall back to the existing Identity authorization.
        /// </summary>
        public static async Task<User> AuthenticateAsync(HttpContext context, string fusionPBXConnectionString)
        {
            string? token = GetBearerToken(context);

            if (string.IsNullOrWhiteSpace(token) || string.IsNullOrWhiteSpace(fusionPBXConnectionString))
            {
                return default;
            }

            try
            {
                var user = await User.GetByApiKeyAsync(token.AsMemory(), fusionPBXConnectionString.AsMemory());

                if (user.user_uuid == Guid.Empty)
                {
                    return default;
                }

                // Older FusionPBX schemas store user_enabled as the text 'true' or 'false'; newer ones use a boolean
                // column, which Dapper maps into this string as "True" or "False". Accept both.
                if (!string.Equals(user.user_enabled, "true", StringComparison.OrdinalIgnoreCase))
                {
                    Log.Warning("[FusionPBX] API key matched user {Username} but user_enabled is {UserEnabled}", user.username, user.user_enabled);
                    return default;
                }

                return user;
            }
            catch (Exception ex)
            {
                Log.Error("[FusionPBX] Failed to authenticate an API key against the FusionPBX database: {Message}", ex.Message);
                return default;
            }
        }

        /// <summary>
        /// Is the supplied FusionPBX user a real, enabled user?
        /// </summary>
        public static bool IsAuthenticated(this User user) => user.user_uuid != Guid.Empty;

        /// <summary>
        /// The FusionPBX destination for the supplied phone number, if it is registered to the authenticated user's
        /// domain; otherwise a default DestinationDetails (destination_uuid == Guid.Empty). Matching tolerates country
        /// code prefixes, so +12065551234 and 12065551234 both match a destination stored as 2065551234.
        /// </summary>
        public static async Task<DestinationDetails> GetOwnedDestinationAsync(this User user, string dialedNumber, string fusionPBXConnectionString)
        {
            if (!user.IsAuthenticated() || string.IsNullOrWhiteSpace(dialedNumber))
            {
                return default;
            }

            try
            {
                return await DestinationDetails.GetByDialedNumberAndDomainAsync(
                    dialedNumber.AsMemory(), user.domain_uuid ?? Guid.Empty, fusionPBXConnectionString.AsMemory());
            }
            catch (Exception ex)
            {
                Log.Error("[FusionPBX] Failed to verify number ownership against the FusionPBX database: {Message}", ex.Message);
                return default;
            }
        }

        /// <summary>
        /// Does the authenticated FusionPBX user own the supplied phone number? Ownership means the number is a
        /// destination registered to the user's domain in FusionPBX.
        /// </summary>
        public static async Task<bool> OwnsNumberAsync(this User user, string dialedNumber, string fusionPBXConnectionString)
            => (await user.GetOwnedDestinationAsync(dialedNumber, fusionPBXConnectionString)).destination_uuid != Guid.Empty;
    }
}
